changeSet.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='sms_notification_enabled') THEN
        ALTER TABLE document.template DROP COLUMN sms_notification_enabled;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='sms_notification_text') THEN
        ALTER TABLE document.template DROP COLUMN sms_notification_text;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='firebase_notification_enabled') THEN
        ALTER TABLE document.template DROP COLUMN firebase_notification_enabled;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='template' AND column_name='firebase_notification_text') THEN
        ALTER TABLE document.template DROP COLUMN firebase_notification_text;
    END IF;
END $$;
